/* Discrete PID with anti-windup, derivative filter and no setpoint kick. */
typedef struct {
    float kp, ki, kd;      /* gains, ki and kd already scaled by Ts */
    float n;               /* derivative filter: 1 + Tf/Ts, with Tf = Kd/(N*Kp) */
    float integral;
    float meas_prev;
    float d_state;
    float out_min, out_max;
} pid_ctrl_t;

float pid_step(pid_ctrl_t *c, float setpoint, float meas)
{
    float error = setpoint - meas;

    /* proportional */
    float p = c->kp * error;

    /* derivative on measurement, filtered */
    float d_raw = -(meas - c->meas_prev);
    c->d_state += (d_raw - c->d_state) / c->n;
    float d = c->kd * c->d_state;
    c->meas_prev = meas;

    /* tentative output before integrating */
    float out = p + c->integral + d;

    /* conditional integration: hold when saturated and pushing further */
    int saturated_high = (out > c->out_max) && (error > 0.0f);
    int saturated_low  = (out < c->out_min) && (error < 0.0f);
    if (!saturated_high && !saturated_low) {
        c->integral += c->ki * error;
        out = p + c->integral + d;
    }

    /* clamp */
    if (out > c->out_max) out = c->out_max;
    if (out < c->out_min) out = c->out_min;
    return out;
}

/* Lead compensator C(s) = 4 (s + 10)/(s + 20), Tustin, T = 10 ms */
#define B0   3.818182f
#define B1  -3.454545f
#define A1   0.818182f      /* u[k] = A1 u[k-1] + B0 e[k] + B1 e[k-1] */
#define UMAX 24.0f

static float e_prev, u_prev;

float lead_step(float ref, float angle)     /* called every 10 ms */
{
    float e = ref - angle;
    float u = A1 * u_prev + B0 * e + B1 * e_prev;
    if (u > UMAX) u = UMAX;                  /* driver limit */
    if (u < -UMAX) u = -UMAX;
    e_prev = e;
    u_prev = u;                              /* the value really applied */
    return u;
}
